// A clean edition uses the same application, with no sample records or sample restoration.
function initializeWorkspace(){
  if(!globalThis.SOCLE_BLANK)return;
  const state=JSON.parse(workspaceSnapshot());
  for(const key of Object.keys(state))if(Array.isArray(state[key]))state[key]=[];
  state.company=Object.fromEntries(Object.keys(company).map(key=>[key,'']));
  Object.assign(state.company,{name:'Mon entreprise',blankWorkspace:true,morningBreakMinutes:0,lunchBreakMinutes:0});
  delete state.company.demoProfileVersion;
  state.accountingData={customerInvoices:[],supplierBills:[],expenseReceipts:[],monthlyPayroll:0,vatReserve:0,refinedPayroll:true};
  state.accessAssignments={};state.documentArchives={};state.fleet=[];
  restoreWorkspace(state);
}
const restoreBeforeBlank=restoreWorkspace;
restoreWorkspace=function(state){
  restoreBeforeBlank(state);
  if(state.company?.blankWorkspace){fleet=state.fleet||[];docs.splice(0,docs.length);calendarYear=new Date().getFullYear();}
};
const snapshotBeforeBlank=workspaceSnapshot;
workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeBlank());if(company.blankWorkspace)state.fleet=fleet;return JSON.stringify(state)};
const personalBeforeBlank=personalView;
personalView=function(){if(!people.length)return heading('Mon espace','Ajoutez une personne pour ouvrir son dossier.',false)+`<section class="panel empty"><button class="btn primary" onclick="personForm()">Ajouter une personne</button></section>`;return personalBeforeBlank()};
const profitabilityBeforeBlank=profitabilityView;
profitabilityView=function(){const html=profitabilityBeforeBlank();if(!company.blankWorkspace)return html;return html.replace(/<p class="notice"><strong>Jeu de démonstration[\s\S]*?<\/p>/g,'')};
const homeBeforeBlank=planning;
planning=function(){const html=homeBeforeBlank();if(!company.blankWorkspace||people.length||jobs.length)return html;return `<section class="panel blank-start"><h1>Bienvenue dans votre entreprise</h1><p>Votre espace est vide. Commencez par vos informations, puis ajoutez vos personnes et vos chantiers.</p><div class="modal-actions"><button class="btn primary" onclick="navigate('company')">Renseigner l’entreprise</button><button class="btn" onclick="personForm()">Ajouter une personne</button><button class="btn" onclick="jobForm()">Créer un chantier</button></div></section>`+html};
// Recherche unique : une donnée retrouvée reste liée à son chantier et à son module.
function searchEverywhere(value){
  const host=document.querySelector('.global-search'); if(!host)return;
  host.querySelector('.search-results')?.remove(); const q=String(value||'').trim().toLocaleLowerCase('fr'); if(!q)return;
  const matches=[]; const add=(type,name,detail,action)=>{if([name,detail].join(' ').toLocaleLowerCase('fr').includes(q))matches.push({type,name,detail,action})};
  jobs.forEach(j=>add('Chantier',j.name,`${j.reference||''} · ${j.client||''} · ${j.town||''}`,`showJob('${jsString(j.id)}')`));
  people.forEach(p=>add('Personne',p.name,p.role||'',`personForm(${p.id})`));
  teams.forEach(t=>add('Équipe',t.name,`${t.members.length} personne(s)`,`teamForm(${t.id})`));
  tasks.forEach(t=>add('Tâche',t.title,`${t.owner||''} · ${t.date||''}`,`showTask(${t.id})`));
  reminders.forEach(r=>add('Tâche',r.title,`${r.kind||''} · ${r.date||''}`,`showReminder('${esc(r.id)}')`));
  quotes.forEach(qt=>add('Devis',qt.ref||qt.title,qt.title||'',`showQuote(${qt.id})`));
  assets.forEach(a=>add('Matériel',a.name,a.category||'',`assetForm(${a.id})`));
  (accountingData.customerInvoices||[]).forEach(i=>add('Facture client',i.ref||i.client,`${i.client||''} · ${i.amount||0} €`,`navigate('accounting')`));
  allDocuments().forEach(d=>add('Document',d.name,`${d.type||''} · ${d.owner||''}`,`navigate('documents')`));
  const result=document.createElement('div'); result.className='search-results';
  result.innerHTML=matches.slice(0,8).map(m=>`<button type="button" onclick="document.querySelector('#globalSearch').value='';this.closest('.search-results').remove();${m.action}"><strong>${esc(m.name)}</strong><small>${esc(m.type)} · ${esc(m.detail)}</small></button>`).join('')||'<p>Aucun résultat. Essayez le nom d’un chantier, d’une personne, d’un document ou d’une facture.</p>';
  host.append(result);
}
// Comptabilité reliée au terrain : toute pièce peut être rattachée à un chantier
// puis rapprochée d'une transaction, sans recopier ses informations.
function ensureConnectedAccounting(){
  accountingData??={}; accountingData.customerInvoices??=[]; accountingData.supplierBills??=[];
  accountingData.expenseReceipts??=[]; accountingData.bankTransactions??=[];
}
const restoreBlankAccounting=restoreWorkspace;
restoreWorkspace=function(state){restoreBlankAccounting(state);ensureConnectedAccounting()};
ensureConnectedAccounting();
function supplierBillForm(jobId=0){const job=jobs.find(j=>j.id===jobId);modal('Ajouter une facture fournisseur',`<form onsubmit="saveSupplierBill(event)"><div class="form-two"><label>Fournisseur<input name="supplier" required maxlength="120" placeholder="Ex. BigMat"></label><label>Référence fournisseur<input name="ref" maxlength="80" placeholder="N° facture"></label><label>Date<input name="date" type="date" required value="${reference}"></label><label>Échéance<input name="due" type="date" required value="${reference}"></label><label>Montant TVAC (€)<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Chantier<select name="job"><option value="0">Frais généraux</option>${jobs.map(j=>`<option value="${j.id}" ${j.id===job?.id?'selected':''}>${esc(j.name)} · ${esc(j.client)}</option>`).join('')}</select></label></div><label>Note<input name="note" maxlength="300" placeholder="Matériaux, sous-traitance, location…"></label><p class="notice">La facture sera visible dans le chantier choisi, dans les coûts et dans le rapprochement bancaire.</p><div class="modal-actions"><button class="btn primary">Enregistrer la facture fournisseur</button></div></form>`) }
function saveSupplierBill(event){event.preventDefault();const f=new FormData(event.target),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0)return;ensureConnectedAccounting();accountingData.supplierBills.push({id:'bill-'+crypto.randomUUID(),supplier:f.get('supplier').trim(),ref:f.get('ref').trim(),date:f.get('date'),due:f.get('due'),amount,job:+f.get('job'),note:f.get('note').trim(),status:'À payer',matchedTransactionId:''});closeModal();render();toast('Facture fournisseur reliée au chantier.')}
function bankTransactionForm(){modal('Ajouter une transaction bancaire',`<form onsubmit="saveBankTransaction(event)"><div class="form-two"><label>Date<input name="date" type="date" required value="${reference}"></label><label>Montant (€)<input name="amount" type="number" step="0.01" required placeholder="-2481,24"></label></div><label>Libellé bancaire<input name="label" required maxlength="160" placeholder="Ex. Virement BigMat"></label><p class="notice">Utilisez un montant négatif pour une sortie et positif pour un encaissement. Ouvrane proposera les pièces du même montant.</p><div class="modal-actions"><button class="btn primary">Ajouter la transaction</button></div></form>`) }
function saveBankTransaction(event){event.preventDefault();const f=new FormData(event.target),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||!f.get('label').trim())return;ensureConnectedAccounting();accountingData.bankTransactions.unshift({id:'bank-'+crypto.randomUUID(),date:f.get('date'),amount,label:f.get('label').trim(),matchedType:'',matchedId:''});closeModal();render();toast('Transaction ajoutée. Rapprochez-la d’une pièce.')}
function billForTransaction(transaction){return accountingData.supplierBills.find(b=>b.id===transaction.matchedId)||accountingData.customerInvoices.find(i=>String(i.id)===String(transaction.matchedId))}
function matchingCandidates(transaction){const amount=Math.abs(Number(transaction.amount));const source=transaction.amount<0?accountingData.supplierBills.filter(b=>b.status!=='Payée'):accountingData.customerInvoices.filter(i=>i.status!=='Payée');return source.filter(x=>Math.abs(Number(x.amount)-amount)<.01)}
function reconcileTransaction(id){const tx=accountingData.bankTransactions.find(t=>t.id===id);if(!tx)return;const candidates=matchingCandidates(tx);modal('Rapprocher la transaction',`<p><strong>${esc(tx.label)}</strong><br>${fullDate(tx.date)} · ${money(tx.amount)}</p><p class="notice">Ouvrane propose les pièces ouvertes avec le même montant. Vous gardez toujours la décision finale.</p>${candidates.map(item=>`<button class="doc-link" onclick="confirmReconciliation('${jsString(tx.id)}','${jsString(item.id)}')"><span><strong>${esc(item.ref||item.supplier)}</strong><small>${esc(item.supplier||item.client||'')} · ${esc(jobs.find(j=>j.id===item.job)?.name||'Frais généraux')}</small></span><strong>${money(item.amount)}</strong></button>`).join('')||'<div class="empty">Aucune pièce ouverte avec ce montant. Ajoutez la facture, ou vérifiez le montant.</div>'}`)}
function confirmReconciliation(transactionId,documentId){const tx=accountingData.bankTransactions.find(t=>t.id===transactionId),bill=accountingData.supplierBills.find(b=>b.id===documentId),invoice=accountingData.customerInvoices.find(i=>String(i.id)===String(documentId)),item=bill||invoice;if(!tx||!item)return;tx.matchedType=bill?'supplierBill':'customerInvoice';tx.matchedId=item.id;item.status='Payée';item.paidAt=tx.date;item.matchedTransactionId=tx.id;closeModal();render();toast('Transaction rapprochée. La pièce est marquée payée.')}
const accountingBeforeConnectedWorkflow=accountingView;
accountingView=function(){ensureConnectedAccounting();const base=accountingBeforeConnectedWorkflow(),bills=accountingData.supplierBills,transactions=accountingData.bankTransactions;return base+`<section class="panel connected-accounting"><div class="panel-head"><div><p class="eyebrow">FACTURES FOURNISSEURS</p><h2>À payer et coûts de chantier</h2></div><button class="btn primary" onclick="supplierBillForm()">+ Facture fournisseur</button></div><div class="data-table"><table><thead><tr><th>Fournisseur</th><th>Chantier</th><th>Échéance</th><th>Montant</th><th>État</th></tr></thead><tbody>${bills.map(b=>`<tr><td><strong>${esc(b.supplier)}</strong><small>${esc(b.ref||b.note||'Sans référence')}</small></td><td>${esc(jobs.find(j=>j.id===b.job)?.name||'Frais généraux')}</td><td>${fullDate(b.due||b.date)}</td><td><strong>${money(b.amount)}</strong></td><td><span class="badge ${b.status==='Payée'?'green':'warn'}">${esc(b.status)}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Aucune facture fournisseur.</td></tr>'}</tbody></table></div></section><section class="panel connected-accounting"><div class="panel-head"><div><p class="eyebrow">BANQUE</p><h2>Rapprochements proposés</h2></div><button class="btn primary" onclick="bankTransactionForm()">+ Transaction bancaire</button></div><div class="data-table"><table><thead><tr><th>Date</th><th>Libellé</th><th>Montant</th><th>Pièce proposée</th><th></th></tr></thead><tbody>${transactions.map(t=>{const matched=billForTransaction(t),proposals=matchingCandidates(t);return `<tr><td>${fullDate(t.date)}</td><td><strong>${esc(t.label)}</strong></td><td><strong>${money(t.amount)}</strong></td><td>${matched?`<span class="badge green">Rapprochée · ${esc(matched.ref||matched.supplier)}</span>`:proposals.length?`<span class="badge warn">${proposals.length} proposition(s)</span>`:'<span class="subtle">À identifier</span>'}</td><td>${matched?'':`<button class="btn" onclick="reconcileTransaction('${jsString(t.id)}')">Rapprocher</button>`}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Aucune transaction bancaire importée ou ajoutée.</td></tr>'}</tbody></table></div></section>`};
const showJobBeforeConnectedAccounting=showJob;
showJob=function(id){showJobBeforeConnectedAccounting(id);if(typeof canFieldAction==='function'&&!canFieldAction('viewProfitability'))return;ensureConnectedAccounting();const job=jobs.find(j=>j.id===id),root=document.querySelector('#modalbody .modal-inner');if(!job||!root)return;const bills=accountingData.supplierBills.filter(b=>b.job===id),invoices=accountingData.customerInvoices.filter(i=>i.job===id),costs=bills.reduce((sum,b)=>sum+Number(b.amount||0),0);root.insertAdjacentHTML('beforeend',`<section class="job-detail-section connected-job-finance"><div class="section-heading"><div><h3>Achats & factures</h3><span class="subtle">Ces coûts sont rattachés à ce chantier.</span></div><button class="btn" onclick="supplierBillForm(${id})">+ Facture fournisseur</button></div><div class="job-finance-summary"><span><small>Facturé client</small><strong>${money(invoices.reduce((sum,i)=>sum+Number(i.amount||0),0))}</strong></span><span><small>Achats fournisseurs</small><strong>${money(costs)}</strong></span></div>${bills.map(b=>`<div class="detail-row"><span><strong>${esc(b.supplier)}</strong><small>${esc(b.ref||b.note||'Facture fournisseur')}</small></span><b>${money(b.amount)}<small>${esc(b.status)}</small></b></div>`).join('')||'<p class="person-empty">Aucune facture fournisseur rattachée.</p>'}</section>`) };
const accessMembersBeforeBlank=accessMembers;
accessMembers=function(){const members=accessMembersBeforeBlank();if(company.blankWorkspace){members[0].name=company.manager||'Propriétaire';members[0].initials=company.manager?company.manager.split(' ').map(s=>s[0]).slice(0,2).join(''):'P'}return members};
const renderBeforeBlank=render;
render=function(){if(company.blankWorkspace)ensureBlankRecords();renderBeforeBlank();if(!company.blankWorkspace)return;const demo=document.querySelector('.demo'),avatar=document.querySelector('.header-right .avatar');if(demo)demo.textContent='Votre espace entreprise';if(avatar)avatar.textContent=company.manager?company.manager.split(' ').map(s=>s[0]).slice(0,2).join(''):'P';document.querySelectorAll('.personal-head label').forEach(label=>{if(label.firstChild?.nodeType===3)label.firstChild.textContent='Personne affichée '});};
