const overviewTab=tabs2.find(tab=>tab[0]==='planning');if(overviewTab)overviewTab[1]='Vue d’ensemble';
if(!tabs2.some(tab=>tab[0]==='schedule'))tabs2.splice(Math.max(0,tabs2.findIndex(tab=>tab[0]==='planning')+1),0,['schedule','Planning']);
let scheduleRange='week',scheduleGroup='team';
function scheduleDates(){const count={today:1,week:5,twoWeeks:10,month:20}[scheduleRange]||5;const start=new Date((day||reference)+'T12:00:00');return Array.from({length:count},(_,i)=>{const value=new Date(start);value.setDate(start.getDate()+i);return value.toISOString().slice(0,10)})}
function scheduleRows(){if(scheduleGroup==='job')return jobs.map(job=>({id:job.id,name:job.name,sub:job.client||'',matches:a=>a.job===job.id}));if(scheduleGroup==='person')return people.map(person=>({id:person.id,name:person.name,sub:person.role||'',matches:a=>(a.people||teams.find(t=>t.id===a.team)?.members||[]).includes(person.id)}));if(scheduleGroup==='resource')return [...fleet.map(asset=>({id:'fleet-'+asset.id,name:asset.name,sub:asset.vehicle?.registration||asset.category||'',matches:a=>a.vehicle===asset.id})),...subcontractors.map(item=>({id:item.id,name:item.name,sub:item.trade||'Sous-traitant',matches:a=>a.subcontractor===item.id}))];return teams.map(team=>({id:team.id,name:team.name,sub:`${team.members.length} personne(s)`,matches:a=>a.team===team.id}))}
function scheduleView(){const dates=scheduleDates(),rows=scheduleRows(),labels={team:'Équipe',person:'Personne',job:'Chantier',resource:'Ressource'};return heading('Planning','Préparez les équipes, personnes, chantiers et ressources au même endroit.',false)+`<section class="planning-workspace"><div class="planning-toolbar"><div class="filter-pills">${[['today','Aujourd’hui'],['week','Semaine'],['twoWeeks','2 semaines'],['month','Mois']].map(([key,label])=>`<button class="${scheduleRange===key?'selected':''}" onclick="scheduleRange='${key}';render()">${label}</button>`).join('')}</div><div class="filter-pills">${Object.entries(labels).map(([key,label])=>`<button class="${scheduleGroup===key?'selected':''}" onclick="scheduleGroup='${key}';render()">Par ${label.toLowerCase()}</button>`).join('')}</div><button class="btn primary" onclick="assignForm()">+ Planifier</button></div><div class="schedule-grid" style="--schedule-days:${dates.length}"><div class="schedule-head"><span>${labels[scheduleGroup]}</span>${dates.map(d=>`<span>${new Date(d+'T12:00:00').toLocaleDateString('fr-BE',{weekday:'short',day:'numeric',month:'short'})}</span>`).join('')}</div>${rows.map(row=>`<div class="schedule-row"><strong>${esc(row.name)}<small>${esc(row.sub)}</small></strong>${dates.map(date=>{const assignment=assignments.find(a=>a.date===date&&row.matches(a)),job=jobs.find(j=>j.id===assignment?.job),team=teams.find(t=>t.id===assignment?.team);return assignment?`<button draggable="true" class="schedule-slot filled" ondragstart="startPlanningDrag(event,${assignment.id})" onclick="assignForm(${assignment.id})"><b>${esc(job?.name||team?.name||'Affectation')}</b><small>${esc(team?.name||'')}</small></button>`:`<button class="schedule-slot" ondragover="event.preventDefault()" ondrop="dropPlanningAssignment(event,'${date}')" onclick="assignForm(0,'${date}',${scheduleGroup==='team'?row.id:0})">+</button>`}).join('')}</div>`).join('')||'<div class="empty">Ajoutez une équipe, un chantier ou une ressource pour préparer le planning.</div>'}</div><p class="help-line">Glissez une affectation vers une autre date pour la déplacer.</p></section>`}
let draggedPlanningAssignment=0,lastPlanningMove=null;
function startPlanningDrag(event,id){draggedPlanningAssignment=id;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(id))}
function dropPlanningAssignment(event,date){event.preventDefault();const id=Number(event.dataTransfer.getData('text/plain')||draggedPlanningAssignment),assignment=assignments.find(item=>item.id===id);if(!assignment||assignment.date===date)return;const collision=assignments.some(item=>item.id!==id&&item.date===date&&item.team===assignment.team);if(collision)return toast('Cette équipe est déjà affectée ce jour-là.');lastPlanningMove={id,from:assignment.date};assignment.date=date;render();toast('Planning modifié — Annuler')}
function undoPlanningMove(){if(!lastPlanningMove)return;const assignment=assignments.find(item=>item.id===lastPlanningMove.id);if(assignment)assignment.date=lastPlanningMove.from;lastPlanningMove=null;render();toast('Déplacement annulé.')}
function jobContactPicker(jobId){modal('Associer un contact',`${contacts.map(c=>`<button class="doc-link" onclick="linkContactToJob('${jsString(c.id)}',${jobId})"><span><strong>${esc(c.name)}</strong><small>${esc(c.company||c.roles.join(' · '))}</small></span><span>Ajouter</span></button>`).join('')||'<div class="empty">Ajoutez d’abord un contact dans l’annuaire.</div>'}`)}
function linkContactToJob(contactId,jobId){const job=jobs.find(j=>j.id===jobId);if(!job)return;job.contactIds??=[];if(!job.contactIds.includes(contactId))job.contactIds.push(contactId);closeModal();openJobWorkspace(jobId);toast('Contact associé au chantier.')}
