const jobFormWithContacts=jobForm;jobForm=function(){jobFormWithContacts();const form=document.querySelector('#modalbody form'),client=form?.querySelector('[name="client"]');if(!client)return;const list=document.createElement('datalist');list.id='knownClients';list.innerHTML=contacts.filter(c=>c.roles.includes('Client')).map(c=>`<option value="${esc(c.name)}">${esc(c.company||'')}</option>`).join('');document.querySelector('#modalbody').append(list);client.setAttribute('list','knownClients');client.insertAdjacentHTML('afterend','<small class="subtle">Commencez à taper pour réutiliser un client de l’annuaire.</small>')};
const saveJobWithContacts=saveJob;saveJob=function(event){const client=String(new FormData(event.target).get('client')||'').trim(),before=jobs.length;saveJobWithContacts(event);if(jobs.length<=before)return;const job=jobs.at(-1),contact=contacts.find(c=>c.roles.includes('Client')&&c.name.localeCompare(client,'fr',{sensitivity:'base'})===0);if(contact){job.contactIds=[contact.id];toast('Chantier créé et relié au client de l’annuaire.')}else job.contactIds=[]};
let jobQuery='',jobPhase='Tous',savedJobViews=[];
