jobsView=function(){const phases=['Tous',...new Set(jobs.map(job=>job.phase||'À préparer'))],list=jobs.filter(job=>(jobPhase==='Tous'||job.phase===jobPhase)&&[job.name,job.client,job.town,job.type].join(' ').toLocaleLowerCase('fr').includes(jobQuery.toLocaleLowerCase('fr')));return heading('Chantiers','Retrouvez rapidement le chantier, le client et l’état d’avancement.',false)+`<div class="saved-view-bar"><div class="filter-pills">${savedJobViews.map(view=>`<button onclick="applyJobView('${view.id}')">${esc(view.name)}</button>`).join('')}</div><button class="link" onclick="saveJobView()">Enregistrer cette vue</button></div><div class="catalogue-tools"><input placeholder="Rechercher un chantier, client ou ville…" value="${esc(jobQuery)}" oninput="jobQuery=this.value;render()"><button class="btn primary" onclick="jobForm()">+ Nouveau chantier</button></div><div class="filter-pills">${phases.map(phase=>`<button class="${jobPhase===phase?'selected':''}" onclick="jobPhase='${jsString(phase)}';render()">${esc(phase)}</button>`).join('')}</div><section class="panel">${list.map(job=>`<button class="task" onclick="openJobWorkspace(${job.id})"><span class="task-text"><strong>${esc(job.name)}</strong><small>${esc(job.client||'Client à renseigner')} · ${esc(job.town||'Ville à renseigner')}</small></span><span class="badge">${esc(job.phase||'À préparer')}</span><span>${job.progress||0} %</span><span>↗</span></button>`).join('')||'<div class="empty">Aucun chantier dans cette vue.</div>'}</section>`};
const onboardingBase=[['identity','Identité vérifiée'],['contract','Contrat signé'],['bank','Coordonnées bancaires reçues'],['emergency','Contact d’urgence encodé'],['welcome','Accueil et règlement transmis'],['ouvrane','Accès OUVRANE créé']];
function ensureOnboarding(p){p.hr??={};p.hr.onboarding??={vehicleId:'',items:{}};return p.hr.onboarding}function onboardingItems(p){const a=[...onboardingBase];if(['Ouvrier','Apprenti','Intérimaire'].includes(p.category))a.push(['training','Formations requises renseignées'],['safety','Consignes de sécurité remises']);if(ensureOnboarding(p).vehicleId)a.push(['licence','Permis de conduire vérifié'],['vehicle','Véhicule et documents remis']);return a}
function helpTip(text){const id='help-'+crypto.randomUUID();return `<span class="help-tip"><button type="button" class="help-tip-button" aria-label="Afficher l’aide" aria-expanded="false" aria-controls="${id}" onclick="toggleHelpTip(this)">?</button><span id="${id}" class="help-tip-content" role="tooltip">${esc(text)}</span></span>`}
function toggleHelpTip(button){const wasOpen=button.parentElement.classList.contains('open');document.querySelectorAll('.help-tip.open').forEach(item=>{item.classList.remove('open');item.querySelector('button')?.setAttribute('aria-expanded','false')});if(!wasOpen){button.parentElement.classList.add('open');button.setAttribute('aria-expanded','true')}}
document.addEventListener('click',event=>{if(!event.target.closest('.help-tip'))document.querySelectorAll('.help-tip.open').forEach(item=>{item.classList.remove('open');item.querySelector('button')?.setAttribute('aria-expanded','false')})});
function onboardingForm(id){const p=getPerson(id),o=ensureOnboarding(p),labels={todo:'À faire',waiting:'En attente',validation:'À valider',done:'Terminé'};modal('Checklist d’embauche · '+p.name,`<form onsubmit="saveOnboarding(event,${id})"><label>Véhicule attribué ${helpTip('Optionnel. Attribuez un véhicule uniquement s’il est réellement confié à cette personne ; les étapes permis et remise des documents apparaîtront alors.')}<select name="vehicle"><option value="">Aucun véhicule</option>${fleet.map(v=>`<option value="${v.id}" ${+o.vehicleId===v.id?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><p class="notice">Les étapes véhicule ne s’affichent que si un véhicule est attribué.</p>${onboardingItems(p).map(([k,l])=>`<label>${l} ${k==='bank'?helpTip('Indiquez seulement que les coordonnées ont été reçues. Les documents sensibles doivent être déposés dans un espace sécurisé réservé au secrétariat.'):''}<select name="${k}">${Object.entries(labels).map(([s,n])=>`<option value="${s}" ${o.items[k]===s?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<div class="modal-actions"><button class="btn primary">Enregistrer la checklist</button></div></form>`)}
function saveOnboarding(e,id){e.preventDefault();const p=getPerson(id),o=ensureOnboarding(p),f=new FormData(e.target);o.vehicleId=f.get('vehicle');onboardingItems(p).forEach(([k])=>o.items[k]=f.get(k)||'todo');closeModal();render();toast('Checklist d’embauche enregistrée.')}
const personFormOnboarding=personForm;personForm=function(id){personFormOnboarding(id);if(!id)return;const p=getPerson(id),o=ensureOnboarding(p),items=onboardingItems(p),done=items.filter(([k])=>o.items[k]==='done').length,root=document.querySelector('#modalbody .modal-inner');root?.insertAdjacentHTML('beforeend',`<section class="job-detail-section"><div class="section-heading"><div><h3>Dossier d’embauche ${helpTip('Une checklist de suivi : elle ne remplace pas le contrat ni un coffre-fort documentaire. Seules les personnes autorisées doivent accéder aux documents sensibles.')}</h3><span class="subtle">${done} / ${items.length} étape(s) terminée(s)</span></div><button type="button" class="btn" onclick="onboardingForm(${id})">Ouvrir la checklist</button></div></section>`) };
const renderWithPlanningUndo=render;render=function(){const result=renderWithPlanningUndo();if(view==='schedule'&&lastPlanningMove){const main=document.querySelector('#main');if(main&&!main.querySelector('.planning-undo'))main.insertAdjacentHTML('beforeend','<div class="planning-undo">Planning modifié <button class="btn" onclick="undoPlanningMove()">Annuler</button></div>')}return result};

// Les aides ne sont posées que sur les choix qui modifient l'organisation,
// les coûts, ou le suivi d'un chantier.
const scheduleViewWithContextHelp=scheduleView;scheduleView=function(){return scheduleViewWithContextHelp().replace('Préparez les équipes, personnes, chantiers et ressources au même endroit.','Préparez les équipes, personnes, chantiers et ressources au même endroit. '+helpTip('Une affectation relie une équipe ou une personne à un chantier et à une date. Faites glisser un bloc pour le déplacer ; vous pourrez immédiatement annuler.')).replace('Glissez une affectation vers une autre date pour la déplacer.','Glissez une affectation vers une autre date pour la déplacer. '+helpTip('Le déplacement change la date de l’affectation, sans modifier les heures déjà encodées.'))};
const supplierBillFormWithContextHelp=supplierBillForm;supplierBillForm=function(jobId=0){supplierBillFormWithContextHelp(jobId);const form=document.querySelector('#modalbody form');form?.querySelector('label:has([name="job"])')?.insertAdjacentHTML('afterbegin',helpTip('Le chantier choisi reçoit ce coût dans sa rentabilité. Choisissez « Frais généraux » seulement si la dépense ne concerne aucun chantier précis.'))};
const electronicInvoiceFormWithContextHelp=electronicInvoiceForm;electronicInvoiceForm=function(){electronicInvoiceFormWithContextHelp();const form=document.querySelector('#modalbody form');form?.querySelector('label:has([name="enabled"])')?.insertAdjacentHTML('beforeend',' '+helpTip('Cette option prépare les informations de facture. Elle n’envoie rien et ne connecte pas encore OUVRANE à un opérateur Peppol.'));form?.querySelector('label:has([name="endpointId"])')?.insertAdjacentHTML('afterbegin',helpTip('Cet identifiant est fourni par l’opérateur Peppol choisi. Laissez ce champ vide tant qu’aucun opérateur n’est connecté.'))};
const jobWorkspaceWithContextHelp=jobWorkspace;jobWorkspace=function(){return jobWorkspaceWithContextHelp().replace('<h2>À gérer maintenant</h2>','<h2>À gérer maintenant '+helpTip('Les tâches affichées ici sont uniquement celles liées à ce chantier et qui ne sont pas terminées.')+'</h2>').replace('<h2>Heures enregistrées</h2>','<h2>Heures enregistrées '+helpTip('Les heures servent au suivi du chantier. Elles ne constituent pas, à elles seules, une paie ou une validation officielle.')+'</h2>').replace('<h2>Documents & photos</h2>','<h2>Documents & photos '+helpTip('Ajoutez ici les éléments utiles au chantier. Évitez d’y déposer des documents personnels ou confidentiels.')+'</h2>').replace('<h2>Factures fournisseurs</h2>','<h2>Factures fournisseurs '+helpTip('Une facture fournisseur liée au chantier est prise en compte dans ses coûts et dans sa rentabilité.')+'</h2>')};
const actionsWithContextHelp=actions;actions=function(){return actionsWithContextHelp().replace('Une action liée à son chantier, son responsable et son historique.','Une action liée à son chantier, son responsable et son historique. '+helpTip('Les états « À valider », « En attente » et « Problème » servent à signaler clairement ce qui bloque. Une tâche terminée reste dans l’historique.'))};
const contactsViewWithContextHelp=contactsView;contactsView=function(){return contactsViewWithContextHelp().replace('Clients, architectes, fournisseurs et sous-traitants.','Clients, architectes, fournisseurs et sous-traitants. '+helpTip('Un même contact peut avoir plusieurs rôles et être relié à plusieurs chantiers. Évitez les doublons : recherchez-le avant de le créer.')).replace('Importer CSV','Importer CSV '+helpTip('Importez un fichier avec une ligne par contact. Vérifiez les doublons avant de confirmer l’import.'))};

// Ressources de planning : une équipe peut recevoir un véhicule, une machine
// ou un sous-traitant, sans les confondre avec le personnel interne.
let subcontractors=[];
const restoreBeforeSubcontractors=restoreWorkspace;restoreWorkspace=function(state){restoreBeforeSubcontractors(state);subcontractors=Array.isArray(state.subcontractors)?state.subcontractors:[]};
const snapshotBeforeSubcontractors=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeSubcontractors());state.subcontractors=subcontractors;return JSON.stringify(state)};
function subcontractorForm(){modal('Ajouter un sous-traitant',`<form onsubmit="saveSubcontractor(event)"><label>Entreprise<input name="name" required maxlength="120"></label><div class="form-two"><label>Spécialité<input name="trade" maxlength="100" placeholder="Ex. électricité, échafaudage"></label><label>Contact<input name="contact" maxlength="100"></label></div><label>Téléphone<input name="phone" maxlength="40"></label><div class="modal-actions"><button class="btn primary">Enregistrer le sous-traitant</button></div></form>`)}
function saveSubcontractor(event){event.preventDefault();const f=new FormData(event.target);subcontractors.push({id:'sub-'+crypto.randomUUID(),name:f.get('name').trim(),trade:f.get('trade').trim(),contact:f.get('contact').trim(),phone:f.get('phone').trim()});closeModal();render();toast('Sous-traitant ajouté aux ressources.')}
const assignFormBeforeResources=assignForm;assignForm=function(...args){assignFormBeforeResources(...args);const form=document.querySelector('#modalbody form'),id=args[0],assignment=assignments.find(a=>a.id===id)||{};if(!form)return;const insertion=document.createElement('div');insertion.className='form-two planning-resources';insertion.innerHTML=`<label>Véhicule / machine<select name="resource"><option value="">Aucune ressource</option>${fleet.map(item=>`<option value="${item.id}" ${item.id===assignment.vehicle?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><label>Sous-traitant<select name="subcontractor"><option value="">Aucun sous-traitant</option>${subcontractors.map(item=>`<option value="${esc(item.id)}" ${item.id===assignment.subcontractor?'selected':''}>${esc(item.name)}${item.trade?' · '+esc(item.trade):''}</option>`).join('')}</select></label>`;form.querySelector('.form-two')?.after(insertion);form.querySelector('.modal-actions')?.insertAdjacentHTML('beforebegin','<button type="button" class="link" onclick="subcontractorForm()">+ Ajouter un sous-traitant</button>')};
const saveWeeklyAssignmentBeforeResources=saveWeeklyAssignment;saveWeeklyAssignment=function(event,id){const form=new FormData(event.target),resource=Number(form.get('resource')||0),subcontractor=form.get('subcontractor')||'';saveWeeklyAssignmentBeforeResources(event,id);const assignment=id?assignments.find(a=>a.id===id):assignments.at(-1);if(assignment){assignment.vehicle=resource;assignment.subcontractor=subcontractor;render()}};
const renderBlankBeforeSchedule=render;
render=function(){if(view!=='schedule')return renderBlankBeforeSchedule();if(company.blankWorkspace)ensureBlankRecords();document.querySelector('#nav').innerHTML=tabs2.map(([key,label])=>`<button class="${view===key?'active':''}" ${view===key?'aria-current="page"':''} onclick="navigate('${key}')">${label}</button>`).join('');document.querySelector('#main').innerHTML=scheduleView();scheduleSave();};

// Tâches et alertes sont le même objet ; l'état porte toujours un libellé,
// jamais seulement une couleur.
const taskStates={todo:['À faire','warn'],validation:['À valider','blue'],waiting:['En attente','warn'],late:['En retard','red'],problem:['Problème signalé','red'],done:['Terminé','green']};
function effectiveTaskState(item){if(item.state==='done')return 'done';if(item.state==='validation'||item.state==='problem'||item.state==='waiting')return item.state;if(item.date&&item.date<reference)return 'late';return 'todo'}
reminderState=function(item){const state=effectiveTaskState(item),entry=taskStates[state];return [entry[0],entry[1],state]};
const openRemindersWithStates=openReminders;
openReminders=function(){return reminders.filter(item=>effectiveTaskState(item)!=='done').sort((a,b)=>a.date.localeCompare(b.date))};
const reminderRowsWithStates=reminderRows;
reminderRows=function(list){return list.length?list.map(item=>{const [label,tone]=reminderState(item);return `<button class="task alert-row" onclick="showReminder('${jsString(item.id)}')"><span class="alert-date"><b>${new Date(item.date+'T12:00:00').getDate()}</b><small>${new Date(item.date+'T12:00:00').toLocaleDateString('fr-BE',{month:'short'})}</small></span><span class="task-text"><strong>${esc(item.title)}</strong><small>${esc(reminderLabel(item))} · ${esc(item.owner||'Responsable à définir')}</small></span><span class="badge">${esc(item.kind)}</span><span class="badge ${tone}">● ${label}</span><span aria-hidden="true">↗</span></button>`}).join(''):'<div class="empty">Aucune tâche dans cette vue.</div>'};
function setReminderState(id,state){const item=reminders.find(r=>r.id===id);if(!item||!taskStates[state])return;item.state=state==='late'?'todo':state;item.completedAt=state==='done'?new Date().toISOString():'';item.history??=[];item.history.push({action:state,at:new Date().toISOString(),by:company.manager||'Responsable'});closeModal();render();toast(state==='done'?'Tâche terminée.':'État de la tâche mis à jour.')}
showReminder=function(id){const item=reminders.find(r=>r.id===id);if(!item)return;const [label,tone,current]=reminderState(item);modal(item.title,`<span class="badge ${tone}">● ${label}</span><p>${esc(item.note||'Aucune consigne ajoutée.')}</p><div class="detail-row"><span>Échéance</span><b>${fullDate(item.date)}</b></div><div class="detail-row"><span>Responsable</span><b>${esc(item.owner||'À définir')}</b></div><div class="detail-row"><span>Dossier</span><button class="link" onclick="openReminderDossier('${jsString(item.id)}')">${esc(reminderLabel(item))} ↗</button></div><div class="modal-actions"><button class="btn" onclick="reminderForm('${jsString(id)}')">Modifier</button>${current==='done'?`<button class="btn primary" onclick="setReminderState('${jsString(id)}','todo')">Rouvrir</button>`:`<button class="btn" onclick="setReminderState('${jsString(id)}','waiting')">Mettre en attente</button><button class="btn" onclick="setReminderState('${jsString(id)}','validation')">Demander validation</button><button class="btn" onclick="setReminderState('${jsString(id)}','problem')">Signaler un problème</button><button class="btn primary" onclick="setReminderState('${jsString(id)}','done')">Terminer la tâche</button>`}</div>`) };
actions=function(){const order=['todo','validation','waiting','late','problem','done'],tabs=order.map(state=>[state,taskStates[state][0]]),selected=globalThis.alertTab||'todo',list=reminders.filter(item=>effectiveTaskState(item)===selected).sort((a,b)=>a.date.localeCompare(b.date));return heading('Tâches & alertes','Une action liée à son chantier, son responsable et son historique.',false)+`<div class="section-heading"><div class="tabs task-state-tabs">${tabs.map(([state,label])=>`<button class="${selected===state?'selected':''}" onclick="alertTab='${state}';render()">${label} (${reminders.filter(item=>effectiveTaskState(item)===state).length})</button>`).join('')}</div><button class="btn primary" onclick="reminderForm()">+ Créer une tâche</button></div><section class="panel">${reminderRows(list)}</section>`};

// Espace chantier : un détail complet qui garde l'utilisateur dans son contexte.
let currentJobId=0,jobWorkspaceTab='summary';
function openJobWorkspace(id){if(document.querySelector('#modal')?.open)closeModal();currentJobId=id;jobWorkspaceTab='summary';view='jobWorkspace';render()}
const jobsBeforeWorkspace=jobsView;jobsView=function(){return jobsBeforeWorkspace().replaceAll('showJob(','openJobWorkspace(')};
function jobWorkspace(){const job=jobs.find(j=>j.id===currentJobId);if(!job){view='jobs';return jobsView()}ensureConnectedAccounting();const tabs=[['summary','Résumé'],['planning','Planning & équipe'],['field','Terrain'],['documents','Documents'],['finance','Achats & rentabilité'],['history','Historique']],assignment=assignments.filter(a=>a.job===job.id),jobTasks=reminders.filter(r=>r.linkType==='job'&&r.linkId===job.id),bills=accountingData.supplierBills.filter(b=>b.job===job.id),invoices=accountingData.customerInvoices.filter(i=>i.job===job.id),content={summary:`<div class="job-workspace-kpis"><div><small>Avancement</small><strong>${job.progress||0} %</strong></div><div><small>Heures</small><strong>${jobHours(job).toFixed(1)} h</strong></div><div><small>Tâches ouvertes</small><strong>${jobTasks.filter(r=>effectiveTaskState(r)!=='done').length}</strong></div><div><small>Photos</small><strong>${job.photos?.length||0}</strong></div></div><section class="panel"><div class="panel-head"><h2>À gérer maintenant</h2><button class="btn primary" onclick="reminderForm('','job',${job.id})">+ Créer une tâche</button></div>${reminderRows(jobTasks.filter(r=>effectiveTaskState(r)!=='done').slice(0,6))}</section>`,planning:`<section class="panel"><div class="panel-head"><h2>Équipes planifiées</h2><button class="btn primary" onclick="assignForm()">+ Planifier</button></div>${assignment.map(a=>`<div class="detail-row"><span><strong>${fullDate(a.date)}</strong><small>${esc(teams.find(t=>t.id===a.team)?.name||'Équipe')} · ${esc(fleet.find(v=>v.id===a.vehicle)?.name||'Ressource à définir')}</small></span><button class="btn" onclick="assignForm(${a.id})">Modifier</button></div>`).join('')||'<div class="empty">Aucune équipe planifiée.</div>'}</section>`,field:`<section class="panel"><div class="panel-head"><h2>Journal terrain</h2><div><button class="btn" onclick="jobNoteForm(${job.id})">+ Remarque</button><button class="btn primary" onclick="quickContextPhotoForm(${job.id})">📷 Photo</button></div></div>${(job.notes||[]).map(n=>`<article class="job-note"><strong>${esc(n.author||'Équipe')}</strong><p>${esc(n.text)}</p><small>${fullDate(n.date)}</small></article>`).join('')||'<div class="empty">Ajoutez une remarque, une photo ou un problème depuis le terrain.</div>'}</section><section class="panel"><div class="panel-head"><h2>Heures enregistrées</h2><button class="btn" onclick="quickTimeForm(${job.id})">Encoder les heures</button></div>${timeRows(job)}</section>`,documents:`<section class="panel"><div class="panel-head"><h2>Documents & photos</h2><label class="btn primary upload">+ Ajouter des photos<input type="file" accept="image/jpeg,image/png,image/webp" multiple onchange="addPhotos(event,${job.id})"></label></div>${jobDocumentLinks(job)}<div class="photo-grid">${(job.photos||[]).map((p,i)=>`<figure><img src="${p.url}" alt="${esc(p.name)}"><figcaption>${esc(p.name)} <button class="link" onclick="removePhoto(${job.id},${i})">×</button></figcaption></figure>`).join('')}</div></section>`,finance:`<section class="panel"><div class="panel-head"><h2>Factures clients</h2><button class="btn" onclick="invoiceForm()">+ Facture client</button></div>${invoices.map(i=>`<div class="detail-row"><span><strong>${esc(i.ref)}</strong><small>${fullDate(i.due)} · ${esc(i.status)}</small></span><b>${money(i.amount)}</b></div>`).join('')||'<div class="empty">Aucune facture client.</div>'}</section><section class="panel"><div class="panel-head"><h2>Factures fournisseurs</h2><button class="btn primary" onclick="supplierBillForm(${job.id})">+ Facture fournisseur</button></div>${bills.map(b=>`<div class="detail-row"><span><strong>${esc(b.supplier)}</strong><small>${esc(b.ref||b.note||'')} · ${esc(b.status)}</small></span><b>${money(b.amount)}</b></div>`).join('')||'<div class="empty">Aucun achat fournisseur.</div>'}</section>`,history:`<section class="panel"><div class="panel-head"><h2>Historique</h2></div>${[...assignment.map(a=>({date:a.date,text:`Équipe ${teams.find(t=>t.id===a.team)?.name||''} planifiée`})),...(job.timeEntries||[]).map(e=>({date:e.date,text:`Pointage ${e.arrival} → ${e.departure||'en cours'}`})),...jobTasks.map(r=>({date:r.date,text:`Tâche · ${r.title}`}))].sort((a,b)=>b.date.localeCompare(a.date)).map(item=>`<div class="detail-row"><span>${fullDate(item.date)}</span><b>${esc(item.text)}</b></div>`).join('')||'<div class="empty">Aucun événement enregistré.</div>'}</section>`}[jobWorkspaceTab];return `<div class="job-workspace-head"><button class="link" onclick="navigate('jobs')">← Tous les chantiers</button><div><span class="badge">${esc(job.phase||'À préparer')}</span><h1>${esc(job.name)}</h1><p>${esc(job.client||'Client à renseigner')} · ${esc(job.address||job.town||'Adresse à renseigner')}</p></div></div><nav class="job-workspace-tabs">${tabs.map(([key,label])=>`<button class="${key===jobWorkspaceTab?'selected':''}" onclick="jobWorkspaceTab='${key}';render()">${label}</button>`).join('')}</nav>${content}`}
const renderBeforeJobWorkspace=render;render=function(){if(view!=='jobWorkspace')return renderBeforeJobWorkspace();document.querySelector('#nav').innerHTML=tabs2.map(([key,label])=>`<button class="${view===key?'active':''}" onclick="navigate('${key}')">${label}</button>`).join('');document.querySelector('#main').innerHTML=jobWorkspace();scheduleSave()};

// Accueil orienté décision : ce qui doit être géré, ce qui arrive aujourd'hui
// et ce qui mérite une attention avant de devenir un problème.
const planningBeforeDecisionDashboard=planning;
planning=function(){if(!company.blankWorkspace)return planningBeforeDecisionDashboard();const open=openReminders(),today=assignments.filter(a=>a.date===reference),late=open.filter(r=>effectiveTaskState(r)==='late'),watch=jobs.filter(j=>{const planned=Number(j.finance?.plannedHours||0);return planned&&jobHours(j)>planned}).map(j=>({title:`Heures prévues dépassées · ${j.name}`,detail:`${jobHours(j).toFixed(0)} h enregistrées pour ${j.finance.plannedHours} h prévues`,action:`openJobWorkspace(${j.id})`}));return heading('Vue d’ensemble','Les priorités concrètes de votre entreprise, sans statistiques inutiles.',false)+`<section class="decision-dashboard"><div class="decision-section"><div class="panel-head"><div><p class="eyebrow">À TRAITER</p><h2>Ce qui attend une décision</h2></div><button class="btn primary" onclick="reminderForm()">+ Créer une tâche</button></div>${reminderRows([...late,...open.filter(r=>effectiveTaskState(r)==='validation'||effectiveTaskState(r)==='problem')].slice(0,5))}</div><div class="decision-columns"><section class="panel"><div class="panel-head"><div><p class="eyebrow">AUJOURD’HUI</p><h2>Terrain et équipes</h2></div><button class="link" onclick="navigate('schedule')">Ouvrir le planning →</button></div>${today.map(a=>{const team=teams.find(t=>t.id===a.team),job=jobs.find(j=>j.id===a.job);return `<button class="task" onclick="openJobWorkspace(${job?.id})"><span class="task-text"><strong>${esc(job?.name||'Chantier')}</strong><small>${esc(team?.name||'Équipe')} · ${esc(fleet.find(v=>v.id===a.vehicle)?.name||'Ressource à définir')}</small></span><span>↗</span></button>`}).join('')||'<div class="empty">Aucune équipe planifiée aujourd’hui.</div>'}</section><section class="panel"><div class="panel-head"><div><p class="eyebrow">À SURVEILLER</p><h2>Signaux à anticiper</h2></div></div>${[...watch,...open.filter(r=>effectiveTaskState(r)==='waiting').map(r=>({title:r.title,detail:'En attente · '+fullDate(r.date),action:`showReminder('${esc(r.id)}')`}))].map(item=>`<button class="task" onclick="${item.action}"><span class="task-text"><strong>${esc(item.title)}</strong><small>${esc(item.detail)}</small></span><span>↗</span></button>`).join('')||'<div class="empty">Aucun signal particulier.</div>'}</section></div></section>`};

// Navigation mobile legacy neutralisée : mobile-nav.js est désormais l'unique moteur
