// Préparation Peppol : ces informations ne configurent aucun opérateur externe.
function electronicInvoiceSettings(){ensureConnectedAccounting();accountingData.eInvoicing??={enabled:false,endpointId:'',scheme:'BE:VAT'};return accountingData.eInvoicing}
const restoreBeforeElectronicInvoice=restoreWorkspace;restoreWorkspace=function(state){restoreBeforeElectronicInvoice(state);electronicInvoiceSettings()};electronicInvoiceSettings();
function electronicInvoiceForm(){if(typeof canModuleAction!=='function'||!canModuleAction('company','edit')||!canModuleAction('accounting','view'))return denyAccess('La préparation de facturation est réservée au responsable autorisé.');const config=electronicInvoiceSettings();modal('Préparation de facturation électronique',`<form id="v5ElectronicInvoicePreparationForm" onsubmit="saveElectronicInvoiceSettings(event)"><label><input type="checkbox" name="enabled" ${config.enabled?'checked':''}> Marquer les informations comme préparées</label><label>Identifiant de point d’accès envisagé <span class="subtle">(si déjà fourni par votre opérateur)</span><input name="endpointId" maxlength="160" value="${esc(config.endpointId)}" placeholder="Facultatif · information non vérifiée"></label><label>Identifiant entreprise utilisé<select name="scheme"><option value="BE:VAT" ${config.scheme==='BE:VAT'?'selected':''}>N° TVA belge</option><option value="BE:CBE" ${config.scheme==='BE:CBE'?'selected':''}>N° BCE</option></select></label><p class="notice">Ces informations sont conservées dans votre dossier SOCLE. Aucun opérateur Peppol n’est connecté dans cette version : cette préparation ne valide aucun identifiant, ne produit pas de facture structurée et ne permet aucun envoi ni réception Peppol.</p><div class="modal-actions"><button class="btn primary">Enregistrer les informations</button></div></form>`) }
function saveElectronicInvoiceSettings(event){event.preventDefault();if(typeof canModuleAction!=='function'||!canModuleAction('company','edit')||!canModuleAction('accounting','view'))return denyAccess('La préparation de facturation est réservée au responsable autorisé.');const f=new FormData(event.target),config=electronicInvoiceSettings();config.enabled=Boolean(f.get('enabled'));config.endpointId=String(f.get('endpointId')||'').trim();config.scheme=f.get('scheme');closeModal();render();toast('Informations de préparation enregistrées dans SOCLE.')}
const invoiceFormBeforeElectronic=invoiceForm;invoiceForm=function(){invoiceFormBeforeElectronic();const form=document.querySelector('#modalbody form');if(!form)return;const field=document.createElement('label');field.innerHTML=`Mode de facture<select name="deliveryFormat"><option value="PDF">PDF / envoi manuel</option><option value="Peppol" disabled>Peppol · opérateur non connecté</option></select><small class="subtle">Aucun envoi Peppol n’est disponible dans cette version.</small>`;form.insertBefore(field,form.querySelector('.modal-actions'))};
const saveInvoiceBeforeElectronic=saveInvoice;saveInvoice=function(event){const form=new FormData(event.target),format=form.get('deliveryFormat')||'PDF';saveInvoiceBeforeElectronic(event);if(document.querySelector('#modal').open)return;const invoice=accountingData.customerInvoices.at(-1);if(invoice){invoice.deliveryFormat=format;invoice.structuredStatus=format==='Peppol'?'À contrôler avant envoi':'Non structurée'}render()};
const accountingBeforeElectronicInvoice=accountingView;accountingView=function(){const config=electronicInvoiceSettings(),base=accountingBeforeElectronicInvoice(),canPrepare=typeof canModuleAction==='function'&&canModuleAction('company','edit')&&canModuleAction('accounting','view');return base+`<section class="panel electronic-invoice-panel"><div><p class="eyebrow">FACTURATION ÉLECTRONIQUE · PRÉPARATION</p><h2>Peppol · opérateur non connecté</h2><p>${config.enabled?'Des informations sont marquées comme préparées dans votre dossier.':'Les informations de préparation restent à renseigner.'} Aucun envoi, réception ni génération de facture Peppol n’est disponible dans cette version.</p></div>${canPrepare?`<button class="btn ${config.enabled?'':'primary'}" onclick="electronicInvoiceForm()">${config.enabled?'Modifier les informations':'Préparer les informations'}</button>`:''}</section>`};

// Météo normale des chantiers : aujourd'hui et demain, sans consigne métier.
let weatherByTown={},weatherLoading=false;
const weatherLabel=code=>({0:'Ensoleillé',1:'Principalement dégagé',2:'Partiellement nuageux',3:'Couvert',45:'Brouillard',48:'Brouillard givrant',51:'Bruine légère',53:'Bruine modérée',55:'Bruine forte',56:'Bruine verglaçante légère',57:'Bruine verglaçante forte',61:'Pluie légère',63:'Pluie modérée',65:'Pluie forte',66:'Pluie verglaçante légère',67:'Pluie verglaçante forte',71:'Neige légère',73:'Neige modérée',75:'Neige forte',77:'Grains de neige',80:'Averses légères',81:'Averses modérées',82:'Averses fortes',85:'Averses de neige légères',86:'Averses de neige fortes',95:'Orage',96:'Orage avec grêle légère',99:'Orage avec forte grêle'}[Number(code)]||'Conditions variables');
const weatherIcon=code=>[0].includes(Number(code))?'☀️':[1,2].includes(Number(code))?'🌤️':Number(code)===3?'☁️':[45,48].includes(Number(code))?'🌫️':[71,73,75,77,85,86].includes(Number(code))?'❄️':[95,96,99].includes(Number(code))?'⛈️':'🌧️';
function weatherAmount(value,unit='',digits=0){if(value===null||value===undefined||value===''||!Number.isFinite(Number(value)))return 'Indisponible';return Number(value).toLocaleString('fr-BE',{maximumFractionDigits:digits})+unit}
function weatherDayHeading(date){const parts=String(date||'').split('-').map(Number);if(parts.length!==3||parts.some(part=>!Number.isFinite(part)))return 'Date indisponible';const label=new Intl.DateTimeFormat('fr-BE',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(parts[0],parts[1]-1,parts[2],12)));return label.charAt(0).toLocaleUpperCase('fr-BE')+label.slice(1)}
function weatherLocalTime(value){const match=String(value||'').match(/T(\d{2}:\d{2})/);return match?match[1]:'Indisponible'}
function weatherCard(town,data){const daily=data?.daily;if(!daily)return `<button class="weather-card" onclick="loadJobWeather(true,['${jsString(town)}'])"><strong>${esc(town)}</strong><small>Chargement de la météo…</small></button>`;return `<button class="weather-card" aria-label="Prévisions météo détaillées sur 5 jours à ${esc(town)}" title="Ouvrir les prévisions détaillées sur 5 jours" onclick="showTownWeather('${jsString(town)}')"><span>${weatherIcon(daily.weather_code[0])}</span><div><strong>${esc(town)}</strong><small>Aujourd’hui · ${weatherLabel(daily.weather_code[0])} · ${weatherAmount(daily.temperature_2m_max?.[0],'°')} / ${weatherAmount(daily.temperature_2m_min?.[0],'°')} · 5 jours ↗</small></div></button>`}
function weatherDashboard(){const towns=[...new Set(assignments.filter(a=>a.date===reference).map(a=>jobs.find(j=>j.id===a.job)?.town).filter(Boolean))];return towns.length?`<section class="weather-dashboard"><div class="panel-head"><div><p class="eyebrow">MÉTÉO DES CHANTIERS</p><h2>Prévisions</h2></div><button class="link" onclick="loadJobWeather(true)">Actualiser</button></div><div class="weather-cards">${towns.map(town=>weatherCard(town,weatherByTown[town])).join('')}</div></section>`:''}
async function loadJobWeather(force=false,requestedTowns=null){if(weatherLoading)return;const source=Array.isArray(requestedTowns)?requestedTowns:assignments.filter(a=>a.date===reference).map(a=>jobs.find(j=>j.id===a.job)?.town);const towns=[...new Set(source.filter(Boolean))].filter(town=>force||!weatherByTown[town]);if(!towns.length)return;weatherLoading=true;try{await Promise.all(towns.map(async town=>{if(weatherByTown[town]&&!force)return;const geo=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(town)}&count=1&language=fr&format=json`);const place=(await geo.json()).results?.[0];if(!place)return;const forecast=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${place.latitude}&longitude=${place.longitude}&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,precipitation_sum,wind_speed_10m_max,wind_gusts_10m_max,sunrise,sunset&timezone=auto&forecast_days=5`);weatherByTown[town]={place,daily:(await forecast.json()).daily,loadedAt:Date.now()}}));}catch{toast('La météo est momentanément indisponible.')}finally{weatherLoading=false;if(view==='planning'||view==='home')render()}}
function showWeatherForecast(kind,town,data){const daily=data?.daily;if(!daily?.time?.length)return;const count=Math.min(daily.time.length,5),days=daily.time.slice(0,count).map((date,index)=>{const precipitation=weatherAmount(daily.precipitation_probability_max?.[index],' %'),amount=weatherAmount(daily.precipitation_sum?.[index],' mm',1),wind=weatherAmount(daily.wind_speed_10m_max?.[index],' km/h'),gusts=weatherAmount(daily.wind_gusts_10m_max?.[index],' km/h');return `<section class="weather-day"><header class="weather-day-heading"><span class="weather-day-icon" aria-hidden="true">${weatherIcon(daily.weather_code?.[index])}</span><span><h3>${esc(weatherDayHeading(date))}</h3><strong>${esc(weatherLabel(daily.weather_code?.[index]))}</strong></span>${index<2?`<small class="weather-day-relative">${index?'Demain':'Aujourd’hui'}</small>`:''}</header><div class="weather-day-temperature"><span>Maximum <strong>${weatherAmount(daily.temperature_2m_max?.[index],' °C')}</strong></span><span>Minimum <strong>${weatherAmount(daily.temperature_2m_min?.[index],' °C')}</strong></span></div><div class="weather-day-metrics"><div><small>Risque de précipitations</small><strong>${precipitation}</strong></div><div><small>Quantité prévue</small><strong>${amount}</strong></div><div><small>Vent maximum</small><strong>${wind}</strong></div><div><small>Rafales maximum</small><strong>${gusts}</strong></div></div><p class="weather-day-sun">☀️ Lever ${weatherLocalTime(daily.sunrise?.[index])} <span>·</span> Coucher ${weatherLocalTime(daily.sunset?.[index])}</p></section>`}).join('');modal(kind+' · '+town,`<p class="weather-forecast-intro">Prévision détaillée sur ${count} jour${count>1?'s':''} pour ${esc(data.place?.name||town)}.</p><div class="weather-detail" aria-label="Prévisions météo jour par jour">${days}</div><p class="weather-source">Source : <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a> · Prévision indicative, les conditions peuvent évoluer.</p>`)}
function showTownWeather(town){const data=weatherByTown[town];if(!data?.daily?.time?.length)return loadJobWeather(true,[town]);showWeatherForecast('Météo chantier',town,data)}
const planningBeforeWeather=planning;planning=function(){const worker=typeof iaARoleCode==='function'&&iaARoleCode()==='WORKER';return planningBeforeWeather()+(worker?'':weatherDashboard())};
const renderBeforeWeather=render;render=function(){const result=renderBeforeWeather();if(view==='planning'&&!(typeof iaARoleCode==='function'&&iaARoleCode()==='WORKER'))loadJobWeather();return result};

// Listes de travail : vues enregistrées et actions groupées, sans multiplier
// les icônes sur chaque ligne.
let savedTaskViews=[],selectedReminderIds=[];
const restoreBeforeSavedTaskViews=restoreWorkspace;restoreWorkspace=function(state){restoreBeforeSavedTaskViews(state);savedTaskViews=Array.isArray(state.savedTaskViews)?state.savedTaskViews:[]};
const snapshotBeforeSavedTaskViews=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotBeforeSavedTaskViews());state.savedTaskViews=savedTaskViews;return JSON.stringify(state)};
function toggleReminderSelection(id,checked){selectedReminderIds=checked?[...new Set([...selectedReminderIds,id])]:selectedReminderIds.filter(value=>value!==id);render()}
function saveTaskView(){const state=globalThis.alertTab||'todo',name=prompt('Nom de cette vue enregistrée :');if(!name?.trim())return;savedTaskViews.push({id:'view-'+crypto.randomUUID(),name:name.trim(),state});toast('Vue enregistrée.')}
function applyTaskBatch(state){const ids=[...selectedReminderIds];if(!ids.length)return;ids.forEach(id=>{const item=reminders.find(r=>r.id===id);if(item){item.state=state;item.completedAt=state==='done'?new Date().toISOString():''}});selectedReminderIds=[];render();toast(`${ids.length} tâche(s) mise(s) à jour.`)}
actions=function(){const order=['todo','validation','waiting','late','problem','done'],tabs=order.map(state=>[state,taskStates[state][0]]),selected=globalThis.alertTab||'todo',list=reminders.filter(item=>effectiveTaskState(item)===selected).sort((a,b)=>a.date.localeCompare(b.date));return heading('Tâches & alertes','Une action liée à son chantier, son responsable et son historique.',false)+`<div class="saved-view-bar"><div class="filter-pills">${tabs.map(([state,label])=>`<button class="${selected===state?'selected':''}" onclick="alertTab='${state}';selectedReminderIds=[];render()">${label} (${reminders.filter(item=>effectiveTaskState(item)===state).length})</button>`).join('')}${savedTaskViews.map(item=>`<button onclick="alertTab='${jsString(item.state)}';selectedReminderIds=[];render()">${esc(item.name)}</button>`).join('')}</div><button class="link" onclick="saveTaskView()">Enregistrer cette vue</button></div><div class="section-heading"><span class="subtle">${list.length} tâche(s) dans cette vue</span><button class="btn primary" onclick="reminderForm()">+ Créer une tâche</button></div><section class="panel task-batch-list">${list.map(item=>{const [label,tone]=reminderState(item);return `<div class="batch-task" data-task-id="${jsString(item.id)}"><label><input type="checkbox" ${selectedReminderIds.includes(item.id)?'checked':''} onchange="toggleReminderSelection('${jsString(item.id)}',this.checked)" aria-label="Sélectionner ${esc(item.title)}"></label><button class="task" onclick="showReminder('${jsString(item.id)}')"><span class="task-text"><strong>${esc(item.title)}</strong><small>${esc(reminderLabel(item))} · ${esc(item.owner||'Responsable à définir')} · ${fullDate(item.date)}</small></span><span class="badge ${tone}">● ${label}</span></button></div>`}).join('')||'<div class="empty">Aucune tâche dans cette vue.</div>'}</section>${selectedReminderIds.length?`<div class="batch-actions"><strong>${selectedReminderIds.length} sélectionnée(s)</strong><button class="btn" onclick="applyTaskBatch('validation')">À valider</button><button class="btn" onclick="applyTaskBatch('waiting')">En attente</button><button class="btn" onclick="applyTaskBatch('done')">Terminer</button><button class="btn" onclick="selectedReminderIds=[];render()">Annuler</button></div>`:''}`};

function quickCreateMenu(){const items=[];if(typeof canModuleAction==='function'&&canModuleAction('jobs','add'))items.push('<button onclick="jobForm()"><strong>Nouveau chantier</strong><small>Client, nom, adresse et responsable</small></button>');if(typeof canModuleAction==='function'&&canModuleAction('quotes','add'))items.push('<button onclick="quoteForm()"><strong>Nouveau devis</strong><small>Chiffrage relié à un chantier</small></button>');if(typeof canModuleAction==='function'&&canModuleAction('actions','add'))items.push('<button onclick="reminderForm()"><strong>Nouvelle tâche</strong><small>À faire, problème ou validation</small></button>');if(typeof canFieldAction==='function'&&canFieldAction('submitExpense'))items.push('<button onclick="expenseReceiptForm()"><strong>Ajouter une dépense</strong><small>Ticket ou facture relié au chantier</small></button>');if(typeof canModuleAction==='function'&&canModuleAction('jobs','edit'))items.push('<button onclick="quickPhotoFromMobile()"><strong>Ajouter une photo</strong><small>Photo rangée dans le chantier</small></button>');if(typeof canModuleAction==='function'&&canModuleAction('people','add'))items.push('<button onclick="personForm()"><strong>Ajouter une personne</strong><small>Personnel et équipes restent distincts</small></button>');if(!items.length)return denyAccess('Aucune création rapide n’est autorisée pour ce profil.');modal('Créer rapidement','<div class="quick-create-menu">'+items.join('')+'</div>') }
const documentsBeforeBlank=allDocuments;
allDocuments=function(){const list=documentsBeforeBlank();if(!company.blankWorkspace)return list;return list.filter(d=>d.link!=='company'||({ 'company-vat':company.vat,'company-bank':company.iban,'company-insurance':company.companyInsurance,'company-accountant':company.accountant,'company-bce':company.enterpriseNumber}[d.id])).map(d=>d.link==='company'?{...d,date:'',status:'À joindre'}:d)};
const saveJobBeforeBlank=saveJob;
saveJob=function(event){if(!company.blankWorkspace)return saveJobBeforeBlank(event);event.preventDefault();const f=new FormData(event.target);if(!f.get('name').trim())return;jobs.push({id:Math.max(0,...jobs.map(j=>j.id))+1,name:f.get('name').trim(),client:f.get('client').trim(),town:f.get('town').trim(),address:f.get('address').trim(),type:f.get('type').trim(),phase:'À préparer',progress:0,color:'purple',required:[],photos:[]});ensureBlankRecords();closeModal();render();toast('Chantier créé.')};
// A company without staff can still record a task for its owner.
const reminderBeforeBlank=reminderForm;
reminderForm=function(...args){reminderBeforeBlank(...args);if(!company.blankWorkspace)return;const form=document.querySelector('#modal form'),existing=reminders.find(r=>r.id===args[0]);if(form)form.insertAdjacentHTML('beforeend','<label><input type="checkbox" name="forOwner" value="1" '+(!people.length||existing?.forOwner?'checked':'')+'> Pour moi uniquement / le responsable</label>')};
const saveReminderBeforeBlank=saveMultiReminder;
saveMultiReminder=function(event,id){if(!company.blankWorkspace||!new FormData(event.target).get('forOwner'))return saveReminderBeforeBlank(event,id);event.preventDefault();if(!requireField('manageAlerts'))return;const f=new FormData(event.target),title=f.get('title').trim(),[linkType,linkId]=f.get('link').split(':');if(!title)return;const existing=reminders.find(r=>r.id===id),value={title,date:f.get('date'),kind:f.get('kind'),note:f.get('note').trim(),owner:company.manager||'Propriétaire',linkType,linkId:+linkId,recipientIds:[],forOwner:true};if(existing)Object.assign(existing,value);else reminders.push({id:'reminder-'+crypto.randomUUID(),...value,state:'todo',completedAt:''});closeModal();render();toast('Tâche enregistrée pour le responsable.')};

