const actionsCriticalHelp=actions;actions=function(){return actionsCriticalHelp().replace('Une action liée à son chantier, son responsable et son historique.','Une action liée à son chantier, son responsable et son historique. '+helpTip('Les états « À valider », « En attente » et « Problème » servent à signaler clairement ce qui bloque. Une tâche terminée reste dans l’historique.'))};
const electronicInvoiceCriticalHelp=electronicInvoiceForm;electronicInvoiceForm=function(){electronicInvoiceCriticalHelp();const form=document.querySelector('#modalbody form');form?.querySelector('label:has([name="enabled"])')?.insertAdjacentHTML('beforeend',' '+helpTip('Cette option prépare les informations de facture. Elle n’envoie rien et ne connecte pas encore OUVRANE à un opérateur Peppol.'));form?.querySelector('label:has([name="endpointId"])')?.insertAdjacentHTML('afterbegin',helpTip('Cet identifiant est fourni par l’opérateur Peppol choisi. Laissez ce champ vide tant qu’aucun opérateur n’est connecté.'))};

// Liste financière unifiée : mêmes gestes que les tâches (filtrer, mémoriser,
// sélectionner, puis agir), sans modifier une pièce par mégarde.
let financeQuery='',financeStatus='Tous',financeKind='Tous',financeVisibleCount=10,selectedFinanceIds=[],savedFinanceViews=[];
const restoreFinanceViews=restoreWorkspace;restoreWorkspace=function(state){restoreFinanceViews(state);savedFinanceViews=Array.isArray(state.savedFinanceViews)?state.savedFinanceViews:[]};
const snapshotFinanceViews=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotFinanceViews());state.savedFinanceViews=savedFinanceViews;return JSON.stringify(state)};
function financeItems(){ensureConnectedAccounting();const clients=typeof serverInvoices!=='undefined'&&serverFinanceState==='ready'?serverInvoices.map(invoice=>{const legacy=accountingData.customerInvoices.find(item=>String(item.id)===String(invoice.legacySourceId))||{};return {...legacy,id:invoice.id,ref:invoice.invoiceNumber,job:invoice.projectId?Number(invoice.projectId):legacy.job,amount:invoice.totalCents/100,status:invoiceStatusLabel(invoice.status),serverInvoice:true,_kind:'Client',_key:'client:'+invoice.id,_label:legacy.client||'Client'}}):accountingData.customerInvoices.map(item=>({...item,_kind:'Client',_key:'client:'+item.id,_label:item.client}));return [...clients,...accountingData.supplierBills.map(item=>({...item,_kind:'Fournisseur',_key:'supplier:'+item.id,_label:item.supplier}))]}
function visibleFinanceItems(){const query=financeQuery.toLocaleLowerCase('fr');return financeItems().filter(item=>(financeKind==='Tous'||item._kind===financeKind)&&(financeStatus==='Tous'||item.status===financeStatus)&&[item.ref,item._label,item.note,jobs.find(j=>j.id===item.job)?.name].join(' ').toLocaleLowerCase('fr').includes(query))}
function toggleFinanceSelection(key,checked){selectedFinanceIds=checked?[...new Set([...selectedFinanceIds,key])]:selectedFinanceIds.filter(id=>id!==key);render()}
function saveFinanceView(){const name=prompt('Nom de cette vue de factures :');if(!name?.trim())return;savedFinanceViews.push({id:'finance-view-'+crypto.randomUUID(),name:name.trim(),query:financeQuery,status:financeStatus,kind:financeKind});toast('Vue de factures enregistrée.')}
function applyFinanceView(id){const view=savedFinanceViews.find(item=>item.id===id);if(!view)return;financeQuery=view.query;financeStatus=view.status;financeKind=view.kind;selectedFinanceIds=[];render()}
function resetFinanceList(){financeVisibleCount=10;selectedFinanceIds=[];render()}
function showMoreFinance(){financeVisibleCount+=10;render()}
function updateSelectedFinance(status){const selected=financeItems().filter(item=>selectedFinanceIds.includes(item._key)),client=selected.find(item=>item._kind==='Client');if(client){selectedFinanceIds=[];openServerInvoice(client.id);toast('Les factures clients se règlent désormais par paiement serveur ou avoir.');return}const keys=new Set(selectedFinanceIds);selected.filter(item=>item._kind==='Fournisseur').forEach(item=>{const original=accountingData.supplierBills.find(value=>String(value.id)===String(item.id));if(original){original.status=status;if(status==='Payée')original.paidAt=reference}});selectedFinanceIds=[];render();toast('État des factures fournisseurs sélectionnées mis à jour.')}
function showFinanceItem(key){const [kind,id]=key.split(':');if(kind==='client'&&typeof serverInvoiceById==='function'&&serverInvoiceById(id))return openServerInvoice(id);const item=accountingData.supplierBills.find(value=>String(value.id)===id);if(!item)return;modal(item.ref||item.supplier||'Facture',`<div class="detail-row"><span>Fournisseur</span><b>${esc(item.supplier||'')}</b></div><div class="detail-row"><span>Chantier</span><b>${esc(jobs.find(j=>j.id===item.job)?.name||'Frais généraux')}</b></div><div class="detail-row"><span>Échéance</span><b>${fullDate(item.due||item.date)}</b></div><div class="detail-row"><span>Montant</span><b>${money(item.amount)}</b></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Fermer</button></div>`) }
const accountingWithFinanceControls=accountingView;
accountingView=function(){
  const visible=visibleFinanceItems(),displayed=visible.slice(0,financeVisibleCount),statuses=['Tous',...new Set(financeItems().map(item=>item.status))],base=accountingWithFinanceControls();
  const invoices=heading('Factures','Recherchez, filtrez et traitez les factures clients et fournisseurs sans allonger toute la page.',false)+`<section class="panel finance-control-panel"><div class="saved-view-bar"><div class="filter-pills"><button class="${financeKind==='Tous'?'selected':''}" onclick="financeKind='Tous';resetFinanceList()">Toutes</button><button class="${financeKind==='Client'?'selected':''}" onclick="financeKind='Client';resetFinanceList()">Clients</button><button class="${financeKind==='Fournisseur'?'selected':''}" onclick="financeKind='Fournisseur';resetFinanceList()">Fournisseurs</button>${savedFinanceViews.map(view=>`<button onclick="applyFinanceView('${view.id}')">${esc(view.name)}</button>`).join('')}</div><button class="link" onclick="saveFinanceView()">Enregistrer cette vue</button></div><div class="catalogue-tools"><input placeholder="Référence, client, fournisseur ou chantier…" value="${esc(financeQuery)}" oninput="financeQuery=this.value;financeVisibleCount=10;render()"><select onchange="financeStatus=this.value;resetFinanceList()">${statuses.map(status=>`<option ${status===financeStatus?'selected':''}>${esc(status)}</option>`).join('')}</select></div><div class="data-table compact-finance-table"><table><thead><tr><th></th><th>Type</th><th>Pièce</th><th>Chantier</th><th>Échéance</th><th>Montant</th><th>État</th></tr></thead><tbody>${displayed.map(item=>`<tr><td><input type="checkbox" ${selectedFinanceIds.includes(item._key)?'checked':''} onchange="toggleFinanceSelection('${item._key}',this.checked)" aria-label="Sélectionner ${esc(item.ref||item._label)}"></td><td><span class="badge">${item._kind}</span></td><td><button class="link" onclick="showFinanceItem('${item._key}')"><strong>${esc(item.ref||'Sans référence')}</strong><small>${esc(item._label||'')}</small></button></td><td>${esc(jobs.find(j=>j.id===item.job)?.name||'Frais généraux')}</td><td>${fullDate(item.due||item.date)}</td><td><strong>${money(item.amount)}</strong></td><td><span class="badge ${item.status==='Payée'?'green':'warn'}">${esc(item.status||'À traiter')}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Aucune facture dans cette vue.</td></tr>'}</tbody></table></div><div class="finance-list-footer"><span><strong>${displayed.length}</strong> facture(s) affichée(s) sur ${visible.length}</span><div>${visible.length>displayed.length?'<button class="btn" onclick="showMoreFinance()">Afficher 10 de plus</button>':''}${financeVisibleCount>10?'<button class="link" onclick="financeVisibleCount=10;render()">Réduire la liste</button>':''}</div></div>${selectedFinanceIds.length?`<div class="batch-actions"><strong>${selectedFinanceIds.length} sélectionnée(s)</strong><button class="btn primary" onclick="updateSelectedFinance('Payée')">Marquer payée</button><button class="btn" onclick="updateSelectedFinance('À payer')">À payer</button><button class="btn" onclick="selectedFinanceIds=[];render()">Annuler</button></div>`:''}</section>`;
  return base+invoices;
};

let assetQuery='',assetCategoryFilter='Tous',selectedAssetIds=[],savedAssetViews=[];
const restoreAssetViews=restoreWorkspace;restoreWorkspace=function(state){restoreAssetViews(state);savedAssetViews=Array.isArray(state.savedAssetViews)?state.savedAssetViews:[]};
const snapshotAssetViews=workspaceSnapshot;workspaceSnapshot=function(){const state=JSON.parse(snapshotAssetViews());state.savedAssetViews=savedAssetViews;return JSON.stringify(state)};
function visibleAssets(){const query=assetQuery.toLocaleLowerCase('fr');return assets.filter(asset=>(assetCategoryFilter==='Tous'||asset.category===assetCategoryFilter)&&[asset.name,asset.category,asset.provider,asset.reference,asset.attached,asset.responsible].join(' ').toLocaleLowerCase('fr').includes(query))}
function toggleAssetSelection(id,checked){selectedAssetIds=checked?[...new Set([...selectedAssetIds,id])]:selectedAssetIds.filter(value=>value!==id);render()}
function saveAssetView(){const name=prompt('Nom de cette vue matériel :');if(!name?.trim())return;savedAssetViews.push({id:'asset-view-'+crypto.randomUUID(),name:name.trim(),query:assetQuery,category:assetCategoryFilter});toast('Vue matériel enregistrée.')}
function applyAssetView(id){const view=savedAssetViews.find(item=>item.id===id);if(!view)return;assetQuery=view.query;assetCategoryFilter=view.category;selectedAssetIds=[];render()}
function updateSelectedAssets(condition){assets.filter(asset=>selectedAssetIds.includes(asset.id)).forEach(asset=>{asset.condition=condition;asset.history??=[];asset.history.push({date:reference,text:`État mis à jour : ${condition}.`})});selectedAssetIds=[];render();toast('État du matériel sélectionné mis à jour.')}
const fleetWithControls=fleetView;fleetView=function(){const list=visibleAssets(),categories=['Tous',...new Set(assets.map(asset=>asset.category))],all=assets;assets=list;let base;try{base=fleetWithControls()}finally{assets=all}return heading('Matériel','Retrouvez les véhicules, machines et contrats ; ouvrez un dossier pour son détail et son historique.',false)+`<section class="panel finance-control-panel"><div class="saved-view-bar"><div class="filter-pills">${categories.map(category=>`<button class="${assetCategoryFilter===category?'selected':''}" onclick="assetCategoryFilter='${jsString(category)}';selectedAssetIds=[];render()">${esc(category)}</button>`).join('')}${savedAssetViews.map(view=>`<button onclick="applyAssetView('${view.id}')">${esc(view.name)}</button>`).join('')}</div><button class="link" onclick="saveAssetView()">Enregistrer cette vue</button></div><div class="catalogue-tools"><input placeholder="Bien, fournisseur, contrat ou rattachement…" value="${esc(assetQuery)}" oninput="assetQuery=this.value;render()"><button class="btn primary" onclick="assetForm()">+ Ajouter un bien</button></div><div class="data-table"><table><thead><tr><th></th><th>Bien</th><th>Rattachement</th><th>Financement</th><th>État</th><th></th></tr></thead><tbody>${list.map(asset=>`<tr><td><input type="checkbox" ${selectedAssetIds.includes(asset.id)?'checked':''} onchange="toggleAssetSelection(${asset.id},this.checked)" aria-label="Sélectionner ${esc(asset.name)}"></td><td><strong>${esc(asset.name)}</strong><small>${esc(asset.category)}</small></td><td>${esc(asset.attached||'À préciser')}</td><td>${esc(asset.mode||'')}</td><td><span class="badge ${asset.condition==='À réparer'?'warn':'green'}">${esc(asset.condition||'En service')}</span></td><td><button class="link" onclick="showAsset(${asset.id})">Détail ↗</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Aucun bien dans cette vue.</td></tr>'}</tbody></table></div>${selectedAssetIds.length?`<div class="batch-actions"><strong>${selectedAssetIds.length} sélectionné(s)</strong><button class="btn primary" onclick="updateSelectedAssets('En service')">En service</button><button class="btn" onclick="updateSelectedAssets('À réparer')">À réparer</button><button class="btn" onclick="selectedAssetIds=[];render()">Annuler</button></div>`:''}</section>`+base};
